module radix2_div (
    input clk, 
    input rst, 
    input sign, 
    input [7:0] dividend, 
    input [7:0] divisor, 
    input opn_valid, 
    output res_valid, 
    output [15:0] result
);
    reg [7:0] dividend_save;
    reg [7:0] divisor_save;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [7:0] SR;
    reg [3:0] cnt;
    reg [3:0] start_cnt;
    reg [7:0] NEG_DIVISOR;
    reg res_valid_reg;
    assign res_valid = rst ? 1'b0 : cnt[3] ? 1'b1 : (res_valid_reg && !opn_valid) ? 1'b0 : res_valid_reg;
    assign result = {SR, dividend_save};
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            cnt <= 4'd0;
            start_cnt <= 4'd0;
            res_valid_reg <= 1'b0;
        end
        else if(opn_valid && ~res_valid) begin
            dividend_save <= dividend;
            divisor_save <= divisor;
            dividend_abs <= sign ? $unsigned(dividend) : dividend;
            divisor_abs <= sign ? $unsigned(divisor) : divisor;
            SR <= {dividend_abs, 1'b0};
            NEG_DIVISOR <= ~(divisor_abs - 1);
            cnt <= 4'd1;
            start_cnt <= 4'd1;
            res_valid_reg <= 1'b0;
        end
        else if(start_cnt) begin
            if(cnt[3]) begin
                cnt <= 4'd0;
                start_cnt <= 4'd0;
                res_valid_reg <= 1'b1;
                SR <= {1'b0, SR[7:1]};
            end
            else begin
                cnt <= cnt + 1;
                res_valid_reg <= 1'b0;
                SR <= {(SR[6:0] >= NEG_DIVISOR) ? (SR[6:0] + NEG_DIVISOR) : SR[6:0], SR[7]} << 1;
            end
        end
    end

endmodule
